float hash(vec2 p){
  // precision-safe hash (Dave Hoskins): no giant intermediate products,
  // so it stays pattern-free even at large gl_FragCoord values
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);   // quintic: silkier gradients
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(vec2 p){
  float v = 0.0;
  float a = 0.52;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 4; i++){       // fewer octaves = big soft masses, no wisps
    v += a * vnoise(p);
    p = rot * p * 1.9;
    a *= 0.5;
  }
  return v;

void main(){
  vec2 uv = gl_FragCoord.xy / uRes;
  // SCENE SCALE (owner, 2026-09-22): the SKY fits the height — uv.y is the
  // sky coordinate everywhere (0.10 horizon, 0.90 zenith), so the whole
  // sky is always in frame and horizon layers ride the bottom edge. The
  // DETAILS live in uDet, the tighter of height and width/aspect: p is the
  // field frame in detail units (centered), kS converts a window-fraction
  // offset into detail units on each axis. On a landscape window uDet is
  // the height and kS = (W/H, 1): the tuned look, unchanged. On a phone
  // uDet is the width/aspect, so the sun's halo, aureole and arc shrink
  // to fit instead of running off the sides.
  vec2 p  = (gl_FragCoord.xy - 0.5 * uRes) / uDet;
  vec2 kS = uRes / uDet;
  float t = uTime;
  vec2 pw = p - uDrift * t * 0.018;   // advect the whole field downwind

  // one gentle layer of domain warping -> haze that breathes, not smoke that swirls
  vec2 q = vec2(
    fbm(pw * 1.0 + t * vec2(0.010, 0.006)),
    fbm(pw * 1.0 + vec2(5.2, 1.3) - t * vec2(0.007, 0.009))
  );
  vec2 r = vec2(
    fbm(pw * 1.4 + 1.1 * uWarp * q + vec2(1.7, 9.2) + t * vec2(0.0035, -0.0025)),
    fbm(pw * 1.4 + 1.1 * uWarp * q + vec2(8.3, 2.8) - t * vec2(0.0025, 0.0035))
  );
  float f = fbm(pw * 1.1 + 0.8 * uWarp * r);
  f = mix(f, 0.5, 0.35);             // flatten the field: diffuse, defocused

  // vertical 4-stop gradient, gently perturbed by the cloud field
  float g = clamp(uv.y + (f - 0.5) * (0.18 + 0.6 * uDensity) * (0.88 + 0.3 * uv.y), 0.0, 1.0);
  // height compression: an exponent < 1 pushes the sample point up, so
  // the lower stops' colors get squeezed into a SHORTER band — the
  // sunset glow physically sinks with the sun instead of thinning tall
  float gm = pow(g, uSquash);
  vec3 col = mix(uC3, uC2, smoothstep(0.0, 0.45, gm));
  col = mix(col, uC1, smoothstep(0.32, 0.78, gm));
  col = mix(col, uC0, smoothstep(0.62, 1.0, gm));

  // whisper of a vignette
  float vd = length((uv - 0.5) * vec2(uRes.x / uRes.y, 1.0));
  col *= 1.0 - 0.20 * smoothstep(0.6, 1.3, vd);

  // owner color LUT: the Lightroom grade, applied to the finished frame
  // BEFORE the grain/dither (grain rides on top; dither still fights
  // any banding the grade introduces). 33³ strip, two slice taps + mix.
  if (uLutAmt > 0.001){
    vec3 lc = clamp(col, 0.0, 1.0);
    float b33 = lc.b * 32.0;
    float sl0 = floor(b33);
    float sl1 = min(sl0 + 1.0, 32.0);
    vec2 luv0 = vec2((sl0 * 33.0 + lc.r * 32.0 + 0.5) / 1089.0, (lc.g * 32.0 + 0.5) / 33.0);
    vec2 luv1 = vec2((sl1 * 33.0 + lc.r * 32.0 + 0.5) / 1089.0, (lc.g * 32.0 + 0.5) / 33.0);
    vec3 graded = mix(texture2D(uLut, luv0).rgb, texture2D(uLut, luv1).rgb, b33 - sl0);
    col = mix(col, graded, uLutAmt);
  }

  // NIGHT FLOOR (owner, 2026-09-22): the deepest night never falls to
  // black. A screen-lift toward a very dark blue, zenith→horizon, applied
  // AFTER the vignette and the LUT (which push below the grade's own
  // linear floor) and before the grain. The CPU gates it to night, so by
  // day both colors are zero and this is a no-op.
  vec3 nf = mix(uFloorH, uFloorZ, clamp(uv.y, 0.0, 1.0));
  col = nf + col * (1.0 - nf);

  // static photographic grain: three decorrelated taps averaged toward a
  // gaussian, like Photoshop's monochromatic noise (x1.7 restores strength)
  float gn = (hash(gl_FragCoord.xy)
            + hash(gl_FragCoord.xy + 17.13)
            + hash(gl_FragCoord.xy + 41.77)) / 3.0;
  col += (gn - 0.5) * uGrain * 1.7;
  col += (hash(gl_FragCoord.xy * 1.7 + 31.0) - 0.5) * (1.6 / 255.0);

  gl_FragColor = vec4(col, uAlpha);
}
`;

/* ---------- WebGL setup ---------- */
const canvas = $('#gl');
const gl = canvas.getContext('webgl', { antialias: false, alpha: false, powerPreference: 'low-power' })
        || canvas.getContext('experimental-webgl');
let U = null;

function makeShader(type, src){
  const s = gl.createShader(type);
  gl.shaderSource(s, src);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) || 'shader error');
  return s;
}
function initGL(){
  const prog = gl.createProgram();
  gl.attachShader(prog, makeShader(gl.VERTEX_SHADER, VERT));
  gl.attachShader(prog, makeShader(gl.FRAGMENT_SHADER, FRAG));
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog) || 'link error');
  gl.useProgram(prog);

  const buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog, 'aPos');
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

  U = {};
  ['uRes','uDet','uTime','uC0','uC1','uC2','uC3','uGlowPos','uGlowCol','uGlow','uGlowSize','uDensity','uWarp','uGrain','uDrift','uPrecip','uShaft','uFog','uMilk','uDeck','uPuff','uNight','uHaze','uSquash','uTint','uRays','uRayLook','uHalo','uHaloLook','uLut','uLutAmt','uTexV','uCirA','uCirB','uSun','uPolar','uAureole','uWhiten','uPurple','uCrep','uLit','uTintHi','uFloorZ','uFloorH','uDogs','uCorona','uAlpha']
    .forEach(n => { U[n] = gl.getUniformLocation(prog, n); });

  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);   // crossfade compositing

  /* color LUT texture on unit 1 — identity until an owner grade lands.
     NPOT strip (1089×33): CLAMP_TO_EDGE + LINEAR, no mips (WebGL1 rule). */
  const lutTex = gl.createTexture();
  gl.activeTexture(gl.TEXTURE1);
  gl.bindTexture(gl.TEXTURE_2D, lutTex);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1089, 33, 0, gl.RGBA, gl.UNSIGNED_BYTE, identityLutPixels());
  gl.uniform1i(U.uLut, 1);
  gl.activeTexture(gl.TEXTURE0);
  if (LUT_PNG) loadLut(lutTex);
}

function resize(){
  const dpr = Math.min(window.devicePixelRatio || 1, 1.75);
  canvas.width = Math.round(innerWidth * dpr);
  canvas.height = Math.round(innerHeight * dpr);
  gl.viewport(0, 0, canvas.width, canvas.height);
}
/* the detail unit (device px) for a canvas of w×h — see state.scene:
   the tighter of the height and the width ÷ reference aspect */
function detUnit(w, h){
  const keep = w / Math.max(0.1, state.scene.aspect);          // the unit that keeps the composition in frame
  const unit = keep + (h - keep) * clamp(state.scene.crop, 0, 1);   // slide toward the height rule = crop a little
  return Math.max(1, Math.min(h, unit));
}

function buildFrame(){
  const h = localHour();
  const geo = solarGeom(h);
  const wT = state.wTime, wC = state.wCond, wK = state.wTemp;

  /* 1 — the sky gradient. V2: the physical LUT (real sun elevation +
     moon + live aerosol) through the owner's grade. Legacy: the TOD
     keyframes warped by solar geometry. Either way the SAME downstream
     layers (condition, AQI, fog, cloud density) apply on top, and the
     crossfade machinery sees only the resulting cols. */
  const aodPhys = effAod();                         // physical estimate (halo gate needs it)
  const aodNow = dispAod(aodPhys);                  // fx: haze axis pinned pristine when off
  const sunElevDeg = Math.asin(clamp(geo.sinA, -1, 1)) * 180 / Math.PI;
  const seed = daySeed();   // this day's unobservables (see daySeed): read by the corona, the twilight fan, …
  let squashU = 1;   // gradient height compression (sunset)
  let cols;
  {
    const moonElev = SKY2.moonAltitudeDeg(msAtHour(h), state.lat, state.lon);
    cols = SKY2.stops(sunElevDeg, moonElev, moonIllum(), aodNow);
    /* sunset compression: as the sun dips below the horizon, the warm
       glow band sinks with it — a true HEIGHT compression (uSquash
       bends the gradient coordinate so the low stops span less screen),
       plus a soft color cascade that cools the leftover warmth aloft.
       Zero at sunset itself, full ≈ −4.5…−7°, gone by −11° so the
       tuned night gradient is never touched. */
    const dep = -sunElevDeg;
    const w = smooth01(dep / 4.5) * (1 - smooth01((dep - 7) / 4));
    squashU = 1 - 0.45 * w;
    if (w > 0.001){
      cols[1] = lerp3(cols[1], cols[0], 0.28 * w);
      cols[2] = lerp3(cols[2], cols[1], 0.35 * w);
    }
  }

/* NIGHT FLOOR colors (display sRGB) × the night gate: in from −6°, full
   by −12°, so twilight keeps its own colors and the floor owns the
   moonless small hours. Zenith darker than horizon, blue-leaning. */
const nightG = smooth01((-sunElevDeg - 6) / 6);
const ft = clamp(state.night.floor, 0, 1);
const floorZ = lerp3([0.020, 0.028, 0.060], [0.090, 0.120, 0.290], ft).map(v => v * nightG);
const floorH = lerp3([0.030, 0.042, 0.085], [0.125, 0.165, 0.340], ft).map(v => v * nightG);

/* wind: clouds advect downwind; stronger wind = faster drift.
   Gated by the Weather influence; at 0 it keeps a fixed gentle heading. */
const th = (state.windDir + 180) * Math.PI / 180;     // blowing toward (compass)
let dx = lerp(0.86, Math.sin(th), wC);
let dy = lerp(0.50, Math.cos(th), wC);
const dn = Math.hypot(dx, dy) || 1;
const wMag = lerp(1, 0.55 + 1.25 * smooth01(effWind() / 45), wC);
const drift = [dx / dn * wMag, dy / dn * wMag];

const FADE_DUR = 2.5;      // seconds for a full dissolve
const FADE_EPS = 0.02;     // change threshold that triggers a fade
let fadePrev = null, fadeP = 0, lastTarget = null;

function drawParams(f, alpha){
  gl.uniform2f(U.uRes, canvas.width, canvas.height);
  gl.uniform1f(U.uDet, detUnit(canvas.width, canvas.height));
  gl.uniform1f(U.uTime, slowT);
  gl.uniform1f(U.uAlpha, alpha);
  gl.uniform3f(U.uC0, f.cols[0][0], f.cols[0][1], f.cols[0][2]);
  gl.uniform3f(U.uC1, f.cols[1][0], f.cols[1][1], f.cols[1][2]);
  gl.uniform3f(U.uC2, f.cols[2][0], f.cols[2][1], f.cols[2][2]);
  gl.uniform3f(U.uC3, f.cols[3][0], f.cols[3][1], f.cols[3][2]);
  gl.uniform2f(U.uGlowPos, f.glowPos[0], f.glowPos[1]);
  gl.uniform3f(U.uGlowCol, f.glowCol[0], f.glowCol[1], f.glowCol[2]);
  gl.uniform1f(U.uGlow, f.glowStr);
  gl.uniform1f(U.uGlowSize, f.glowSize);
  gl.uniform1f(U.uDensity, f.dens);
  gl.uniform1f(U.uWarp, state.flow);
  gl.uniform1f(U.uGrain, state.grain);
  gl.uniform2f(U.uDrift, f.drift[0], f.drift[1]);
  gl.uniform3f(U.uPrecip, f.precip[0], f.precip[1], f.precip[2]);
  gl.uniform3f(U.uShaft, state.shaftStr, state.shaftCov, state.shaftReach);
  gl.uniform1f(U.uFog, f.fog);
  gl.uniform3f(U.uMilk, f.milk[0], f.milk[1], f.milk[2]);
  gl.uniform1f(U.uDeck, f.deck);
  gl.uniform1f(U.uPuff, f.puff);
  gl.uniform1f(U.uNight, f.night);
  gl.uniform1f(U.uHaze, f.haze);
  gl.uniform1f(U.uSquash, f.squash);
  gl.uniform3f(U.uTint, f.tint[0], f.tint[1], f.tint[2]);
  gl.uniform1f(U.uRays, f.rays);
  gl.uniform2f(U.uRayLook, state.rays.scale, state.rays.falloff);
  gl.uniform1f(U.uHalo, f.halo);
  gl.uniform3f(U.uHaloLook, state.halo.radius, state.halo.dispersion, 1.0);
  gl.uniform1f(U.uLutAmt, state.lutAmt);
  /* grade-shipped texture vibrancy + cirrus look (state-driven, no fade) */
  gl.uniform1f(U.uTexV, SKY2.GRADE.textureVibrancy != null ? SKY2.GRADE.textureVibrancy : 1);
  const ci = state.cirrus;
  gl.uniform4f(U.uCirA, ci.angle * Math.PI / 180, ci.variance * Math.PI / 180, ci.fiber, ci.opacity);
  gl.uniform4f(U.uCirB, ci.cover, ci.evolve, ci.breakDepth, ci.grain);
  /* sun-relative sky geometry + the polarizer band (frame params) */
  gl.uniform3f(U.uSun, f.sun[0], f.sun[1], f.sun[2]);
  gl.uniform1f(U.uPolar, f.polar);
  gl.uniform2f(U.uAureole, f.aureole[0], f.aureole[1]);
  gl.uniform1f(U.uWhiten, f.whiten);
  gl.uniform3f(U.uPurple, f.purple[0], f.purple[1], f.purple[2]);
  gl.uniform2f(U.uCrep, f.crep, state.purity.crepScale);
  gl.uniform3f(U.uLit, f.lit[0], f.lit[1], f.lit[2]);
  gl.uniform3f(U.uTintHi, f.tintHi[0], f.tintHi[1], f.tintHi[2]);
  gl.uniform3f(U.uFloorZ, f.floorZ[0], f.floorZ[1], f.floorZ[2]);
  gl.uniform3f(U.uFloorH, f.floorH[0], f.floorH[1], f.floorH[2]);
  gl.uniform3f(U.uDogs, f.dogs[0], f.dogs[1], f.dogs[2]);
  gl.uniform3f(U.uCorona, f.corona[0], f.corona[1], f.corona[2]);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function drawScene(dt){
  const target = buildFrame();
  if (fadePrev === null && lastTarget && frameDist(target, lastTarget) > FADE_EPS){
    fadePrev = lastTarget;                 // freeze the outgoing sky
    fadeP = 0;
  }
  if (fadePrev){
    fadeP = Math.min(1, fadeP + (dt || 0) / FADE_DUR);
    drawParams(fadePrev, 1.0);             // old sky, still breathing
    drawParams(target, smooth01(fadeP));   // new sky dissolving in over it
    if (fadeP >= 1) fadePrev = null;
  } else {
    drawParams(target, 1.0);
  }
  lastTarget = cloneFrame(target);
}

/* The sky drifts at ~one cloud-length per 80 seconds, so repainting it at
   display rate buys nothing the eye can see. What each repaint DOES buy is
   a bill for everything composited above the canvas: every glass surface
   with a backdrop-filter re-resolves whenever its backdrop changes, and
   each pass syncs on this canvas's shared IOSurface (traced as
   WaitForCommandsToBeScheduled stalls dominating rich-content interaction
   frames). Pacing the shader to ~30fps halves that tax at 60Hz and
   quarters it on ProMotion, for the whole app at once. All sky time below
   is dt-based, so skipped frames change pacing only, never the clock; 31ms
   rather than 33 so the gate never beats against a 16.7ms vsync and lands
   on 30fps exactly. */
const FRAME_MIN_MS = 31;
function frame(now){
  if (now - last < FRAME_MIN_MS){ requestAnimationFrame(frame); return; }
  const dt = Math.min((now - last) / 1000, 0.1);
  last = now;
  slowT += dt * state.speed;                       // "1x" ~= one cloud-length per 80s
  /* custom time is not frozen: it keeps flowing at timeFlow × real
     time, so a chosen golden hour actually unfolds (agency request) */
  if (!state.live){
    state.hourOverride = ((state.hourOverride + dt * state.timeFlow / 3600) % 24 + 24) % 24;
  }
  drawScene(dt);
  requestAnimationFrame(frame);
}

function applyScene(sc){
  state.lat = sc.lat; state.lon = sc.lon; state.place = sc.name; state.tz = sc.tz;
  state.sim = sc.sim;
  state.windSim = sc.wind != null ? sc.wind : null;
  state.aqiSim = sc.aqi != null ? sc.aqi : null;

  /* resolve the named hour against this place's actual sun today */
  const geo = solarGeom(12);
  const H = {
    sunrise: geo.rise + 0.2, morning: geo.rise + 2.5,
    noon: (geo.rise + geo.set) / 2, afternoon: 15.5,
    golden: geo.set - 0.9, sunset: geo.set - 0.2, dusk: geo.set + 0.5,
    night: 23.0, midnight: 0.15
  };
  const h = typeof sc.hour === 'number' ? sc.hour : H[sc.hour];
  state.live = false;
  state.hourOverride = ((h % 24) + 24) % 24;

  activeScene = sc;

  fetchWeather(true);
}

async function fetchWeather(reset){
  const url = 'https://api.open-meteo.com/v1/forecast'
    + '?latitude=' + state.lat + '&longitude=' + state.lon
    + '&current=temperature_2m,weather_code,cloud_cover,is_day,wind_speed_10m,wind_direction_10m,relative_humidity_2m,cloud_cover_low,cloud_cover_mid,cloud_cover_high,wind_gusts_10m'
    /* radiation/visibility/snow/cape aren't served via current= — take
       the current hour from hourly (forecast_hours starts at "now") */
    + '&hourly=visibility,direct_radiation,diffuse_radiation,shortwave_radiation,terrestrial_radiation,snow_depth,cape'
    + '&forecast_hours=2&timezone=auto';
  const aqUrl = 'https://air-quality-api.open-meteo.com/v1/air-quality'
    + '?latitude=' + state.lat + '&longitude=' + state.lon
    + '&current=us_aqi,aerosol_optical_depth';
  const aqP = fetch(aqUrl).then(r => r.ok ? r.json() : null).catch(() => null);
  try {
    const r = await fetch(url);
    if (!r.ok) throw new Error('http ' + r.status);
    const j = await r.json();
    state.temp = j.current.temperature_2m;
    state.code = j.current.weather_code;
    state.cloud = j.current.cloud_cover;
    state.wind = j.current.wind_speed_10m;
    state.windDir = j.current.wind_direction_10m;
    if (j.current.relative_humidity_2m != null) state.humidity = j.current.relative_humidity_2m;
    if (j.current.cloud_cover_low != null) state.cloudLow = j.current.cloud_cover_low;
    if (j.current.cloud_cover_mid != null) state.cloudMid = j.current.cloud_cover_mid;
    if (j.current.cloud_cover_high != null) state.cloudHigh = j.current.cloud_cover_high;
    if (j.current.wind_gusts_10m != null) state.gusts = j.current.wind_gusts_10m;
    const hh = j.hourly;
    if (hh && hh.time && hh.time.length){
      const pick = v => (v && v[0] != null) ? v[0] : null;    // index 0 = the current hour
      state.visibility = pick(hh.visibility);
      state.snowDepth = pick(hh.snow_depth);
      state.cape = pick(hh.cape);
      const dir = pick(hh.direct_radiation), dif = pick(hh.diffuse_radiation);
      const sw = pick(hh.shortwave_radiation), terr = pick(hh.terrestrial_radiation);
      state.diffuseFrac = (dir != null && dif != null && dir + dif > 20) ? dif / (dir + dif) : null;
      state.skyTransmit = (sw != null && terr != null && terr > 50)
        ? clamp(sw / (0.75 * terr), 0, 1.2) : null;
    }
    state.utcOffset = j.utc_offset_seconds;
    state.haveWx = true;
    state.updated = new Date();
  } catch (e) {
    const warn = reset || state.haveWx || !fetchWeather.warned;
    state.haveWx = false;
    if (reset){
      state.temp = 16; state.code = 2; state.cloud = 40;
      state.wind = 9; state.windDir = 250; state.aqi = 35; state.updated = null;
    }
    if (warn){
      toast('Live weather is unreachable — pick a condition chip to simulate');
      fetchWeather.warned = true;
    }
  }
  const aj = await aqP;
  if (aj && aj.current && aj.current.us_aqi != null) state.aqi = aj.current.us_aqi;

window.hark = {
  setLive(on){
    clearScene();
    state.live = !!on;
    if (on) state.dateSim = null;                 // live = here and NOW
    if (!on) state.hourOverride = localHourLiveSnapshot();
    state.stagedCloud = !on;                      // entering custom stages the 42% default
    tick();
  },
  setHour(h){
    clearScene();
    state.hourOverride = ((h % 24) + 24) % 24;
    /* the timeline scrubber tracks 1:1 (owner): drop any in-flight
       dissolve and the fade baseline so dragging moves the sky
       directly — every OTHER state change keeps its crossfade */
    fadePrev = null;
    lastTarget = null;
    tick();
  },
  setDate(s){
    clearScene();
    state.dateSim = s || null;
    if (s && state.live){ state.live = false; state.hourOverride = localHourLiveSnapshot(); }
    tick();
  },
  setTimeFlow(v){ state.timeFlow = clamp(v, 0, 120); },   // 120× = 2 sim minutes per real second
  setSim(code){
    clearScene();
    state.sim = code;
    if (code === null){                            // Live = all auto, REAL cloud
      state.windSim = null; state.aqiSim = null;
      state.cloudSim = null; state.aodSim = null;
      state.stagedCloud = false;                   // dismiss the staged 42% default
    }
    tick();
  },
  setWind(kmh){ state.windSim = kmh; clearScene(); tick(); },
  setAqi(v){ state.aqiSim = v; clearScene(); tick(); },
  setCloud(v){ state.cloudSim = v < 0 ? null : clamp(v, 0, 100); clearScene(); tick(); },
  setAod(v){ state.aodSim = v < 0 ? null : clamp(v, 0.02, 1.5); clearScene(); tick(); },
  setCirrus(k, v){ if (k in state.cirrus) state.cirrus[k] = v; },
  setRays(k, v){ if (k in state.rays) state.rays[k] = v; },
  setHalo(k, v){ if (k in state.halo) state.halo[k] = (k === 'force') ? !!v : v; },
  setPurity(k, v){ if (k in state.purity) state.purity[k] = (k === 'force') ? !!v : v; },
  setScene(k, v){ if (k in state.scene) state.scene[k] = v; },   // scene scale: reference aspect for the detail unit
  setCloudLit(k, v){ if (k in state.cloudLit) state.cloudLit[k] = v; },   // cloud lighting + low-sun dials
  setAfterglow(k, v){ if (k in state.afterglow) state.afterglow[k] = v; },   // re-illumination brightness
  setNight(k, v){ if (k in state.night) state.night[k] = v; },   // night floor dial
  setDogs(k, v){ if (k in state.dogs) state.dogs[k] = (k === 'force') ? !!v : v; },       // sundogs
  setCorona(k, v){ if (k in state.corona) state.corona[k] = (k === 'force') ? !!v : v; },   // coronae
  setLutAmt(v){ state.lutAmt = clamp(v, 0, 1); tick(); },
  setSkyglow(v){ state.skyglowStrength = clamp(v, 0, 1); tick(); },
  /* debug/test hook: override the measured city-light value (null = refetch on next place) */
  setSkyglowSample(v){ state.skyglow = v == null ? null : clamp(v, 0, 1); tick(); },
  applyScene: i => { if (SCENES[i]){ applyScene(SCENES[i]); tick(); } },
  selectPlace: (name, lat, lon, tz) => selectPlace({ name, lat, lon, tz: tz || null }),

function tick(){
  const h = localHour();
  const f = lastTarget || buildFrame();
  const mixP = fadePrev ? smooth01(fadeP) : 1;
  /* lutJS mirrors the GPU grade so the pill dot and the glass
     light/dark switching see the same colors the screen shows */
  const col = i => {
    const c = lutJS(fadePrev ? lerp3(fadePrev.cols[i], f.cols[i], mixP) : f.cols[i]);
    /* the FRAG's night floor (screen-lift, zenith→horizon) — the glass UI
       must switch on the colors the screen actually shows */
    const nf = lerp3(f.floorH, f.floorZ, i === 0 ? 1 : i === 3 ? 0 : (3 - i) / 3);
    return c.map((v, j) => nf[j] + v * (1 - nf[j]));
  };
  const c3 = col(3);
  /* bottom-weighted sky luminance: native flips the glass UI light/dark on it */
  const L = c => 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];
  const lum = 0.1 * L(col(0)) + 0.2 * L(col(1)) + 0.3 * L(col(2)) + 0.4 * L(c3);
  /* true day/night at the displayed hour, from real solar geometry */
  const geo = solarGeom(h);
  const sunR = ((geo.rise % 24) + 24) % 24;
  const isDay = (((h - sunR) % 24) + 24) % 24 < geo.dayLen;
  post({
    type: 'status',
    place: state.place,
    tempF: Math.round(state.temp * 9 / 5 + 32),
    cond: condText(effCode()),
    cloud: Math.round(effCloud()),
    mph: Math.round(effWind() * 0.621371),
    dir: compass(state.windDir),
    aqi: Math.round(effAqi()),
    hour: h,
    timeText: fmtHour(h),
    live: state.live,
    sim: state.sim === null ? -1 : state.sim,
    simActive: state.sim !== null || state.windSim !== null || state.aqiSim !== null
             || state.cloudSim !== null || state.aodSim !== null,
    online: state.haveWx,
    windKmh: effWind(),
    windAuto: state.windSim === null,
    aqiVal: effAqi(),
    aqiAuto: state.aqiSim === null,
    aodVal: effAod(),
    aodAuto: state.aodSim === null,
    cloudAuto: state.cloudSim === null,
    dateSim: state.dateSim || '',
    flow: state.timeFlow,
    scene: activeScene ? activeScene.label : '',
    dot: [c3[0], c3[1], c3[2]],
    lum,
    day: isDay,
    glow: state.skyglow === null ? -1 : state.skyglow,
    /* clear-sky plumbing readouts (phenomena plan, step 0) */
    turb: f.turb,
    seed: f.seed,
    sunAlt: f.sun[2],
    polar: f.polar,
    aureole: f.aureole,
    whiten: f.whiten,
    purple: f.purple[0],
    crep: f.crep,
    dust: f.dust,
    lit: f.lit,
    tintHi: f.tintHi,
    floorZ: f.floorZ,
    floorH: f.floorH,
    dogs: [f.dogs[0], f.dogs[1] / (state.halo.radius / 22)],          // strength, separation in degrees
    corona: [f.corona[0], f.corona[1] / (state.halo.radius / 22), f.corona[2]],   // strength, radius in degrees, purity
    redF: f.redF,
    glowCol: f.glowCol,
    /* scene scale: the detail unit as a share of the height (1 = landscape, tuned look) */
    det: canvas.height > 0 ? detUnit(canvas.width, canvas.height) / canvas.height : 1
  });

try {
  if (!gl) throw new Error('no webgl');
  initGL();
  resize();
  addEventListener('resize', resize);
  loadSnapshot();
  state.lutAmt = LUT_AMT_DEFAULT;
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) state.speed = 0.08;
  post({
    type: 'config',
    sims: SIMS.map(x => ({ label: x[0], code: x[1] === null ? -1 : x[1] })),
    scenes: SCENES.map(x => x.label),
    presets: PRESETS.map(x => x.label)
  });
  fetchWeather();
  setInterval(fetchWeather, 10 * 60 * 1000);
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) fetchWeather();      // app resumed elsewhere/later: refresh, then ease
  });
  setInterval(tick, 1000);
  tick();
  requestAnimationFrame(t => { last = t; requestAnimationFrame(frame); });
} catch (e) {
  document.getElementById('glfail').style.display = 'flex';
  toast('Render failed: ' + (e.message || e));
  console.error(e);
}
